# v116: Looper Paket A – Stimmgerät, Ebenen stumm/löschen, Übe-Tempo (gedehnt, 100 % exakt), Pedal-Belegung (Tippen/Halten/Doppelt)
import asyncio, sys, os, math, struct, wave
from playwright.async_api import async_playwright
U = 'http://localhost:8765/index.html'
ok = 0; tot = 0
def check(n, c, info=''):
    global ok, tot; tot += 1; ok += bool(c); print(('OK    ' if c else 'FEHLER') + '  ' + n + ('  · ' + str(info) if info != '' else ''))
WAV = '/tmp/v116_sine110.wav'
if not os.path.exists(WAV):
    sr = 48000; w = wave.open(WAV, 'wb'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(sr)
    w.writeframes(b''.join(struct.pack('<h', int(12000 * math.sin(2 * math.pi * 110 * i / sr))) for i in range(sr * 4))); w.close()
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(args=['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream', '--use-file-for-fake-audio-capture=' + WAV, '--autoplay-policy=no-user-gesture-required'])
        ctx = await b.new_context(viewport={'width': 1024, 'height': 1366}, bypass_csp=True); await ctx.grant_permissions(['microphone'])
        pg = await ctx.new_page(); errs = []
        pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto(U); await pg.wait_for_timeout(900)
        check('ab v116', int(__import__('re').search(r'v(\d+)', await pg.inner_text('.brand')).group(1)) >= 116)
        sr = await pg.evaluate("(ensureAudio(), audioCtx.sampleRate)")
        # ---------- 1. Stimmgerät ----------
        d = await pg.evaluate("(()=>{const sr=audioCtx.sampleRate,x=new Float32Array(4096);for(let i=0;i<x.length;i++)x[i]=0.5*Math.sin(2*Math.PI*110*i/sr);return Looper.tunerDetect(x,sr,440)})()")
        check('Erkennung direkt: 110-Hz-Sinus = A2, ±2 ct', d and d['name'] == 'A' and d['oct'] == 2 and abs(d['cents']) < 2 and abs(d['f'] - 110) < 0.2, d)
        d2 = await pg.evaluate("(()=>{const sr=audioCtx.sampleRate,x=new Float32Array(4096);for(let i=0;i<x.length;i++)x[i]=0.5*Math.sin(2*Math.PI*82.41*i/sr);return Looper.tunerDetect(x,sr,440)})()")
        check('Erkennung direkt: tiefes E (82,4 Hz) = E2', d2 and d2['name'] == 'E' and d2['oct'] == 2 and abs(d2['cents']) < 3, d2)
        d3 = await pg.evaluate("(()=>{const sr=audioCtx.sampleRate,x=new Float32Array(4096);for(let i=0;i<x.length;i++)x[i]=0.5*Math.sin(2*Math.PI*110*i/sr);return Looper.tunerDetect(x,sr,432)})()")
        check('Kammerton 432 Hz: 110 Hz liegt ~+32 ct über A2', d3 and d3['name'] == 'A' and 28 < d3['cents'] < 36, d3)
        check('Knopf „Stimmen“ neben „Eingang öffnen“', await pg.evaluate("document.getElementById('loopMonitor').nextElementSibling.id") == 'loopTunerBtn')
        await pg.click('#loopTunerBtn'); await pg.wait_for_timeout(2500)
        tu = await pg.evaluate("Looper._tuner()")
        check('Anzeige offen, eigener Abgriff aktiv', await pg.is_visible('#tunerDlg') and tu['an'] and tu['timer'], tu)
        last = tu['last']
        check('Fake-Mikrofon (110-Hz-Sinus): Anzeige A2, grün (±3 ct)', last and last['name'] == 'A' and last['oct'] == 2 and abs(last['cents']) <= 3 and await pg.inner_text('#tunerName') == 'A'
              and await pg.evaluate("document.getElementById('tunerDlg').classList.contains('in-tune')"), (last, await pg.inner_text('#tunerMsg')))
        check('Frequenz angezeigt', '110' in await pg.inner_text('#tunerFreq'), await pg.inner_text('#tunerFreq'))
        await pg.click('#tunerA4p'); await pg.click('#tunerA4p'); await pg.wait_for_timeout(600)
        check('Kammerton 442 Hz eingestellt + gespeichert, 110 Hz jetzt zu tief', await pg.inner_text('#tunerA4v') == '442 Hz' and await pg.evaluate("localStorage.getItem('3nps-tuner-a4')") == '442'
              and await pg.evaluate("Looper._tuner().last && Looper._tuner().last.cents < -5"), await pg.evaluate("Looper._tuner().last"))
        for _ in range(15): await pg.click('#tunerA4p')
        check('Kammerton höchstens 450 Hz', await pg.inner_text('#tunerA4v') == '450 Hz')
        await pg.evaluate("localStorage.setItem('3nps-tuner-a4','440')")
        await pg.click('#tunerClose'); await pg.wait_for_timeout(200)
        tu = await pg.evaluate("Looper._tuner()")
        check('Schließen: Messung und Abgriff aus', not tu['on'] and not tu['an'] and not tu['timer'] and not await pg.is_visible('#tunerDlg'), tu)
        # ---------- 2. Ebenen ----------
        await pg.evaluate("(sr=>{const l=new Float32Array(sr*2).map((_, i)=>Math.sin(i/20)*0.3); Looper._setTrackRaw(0,l); const se=Looper.getSession(); se.baseL=se.tracks[0].L; Looper.loadSession(se)})(%d)" % sr)
        await pg.wait_for_timeout(300)
        check('eine Ebene: keine Ebenen-Leiste', not await pg.is_visible('#layers0'))
        await pg.evaluate("Looper._addLayer(0, new Float32Array(%d*2).fill(0.1))" % sr); await pg.wait_for_timeout(200)
        m = lambda: pg.evaluate("(()=>{const x=Looper._mixOf(0);return [x.l[100], x.l[5000]]})()")
        m2 = await m(); ref = await pg.evaluate("[Math.sin(100/20)*0.3, Math.sin(5000/20)*0.3]")
        check('Overdub als Ebene 2: Leiste mit 1 und 2, Mix = Summe', await pg.is_visible('#layers0') and await pg.locator('#layers0 button').count() == 2 and abs(m2[0] - ref[0] - 0.1) < 1e-4, (m2, ref))
        await pg.click('#layers0 button[data-ly="1"]'); await pg.wait_for_timeout(200)
        m3 = await m()
        check('Ebene 2 stumm → Mix ändert sich (nur Ebene 1)', abs(m3[0] - ref[0]) < 1e-4 and await pg.evaluate("Looper.layers(0)") == [True, False] and 'off' in await pg.get_attribute('#layers0 button[data-ly="1"]', 'class'), m3)
        check('Spur spielt dabei weiter', await pg.evaluate("Looper.debug().tracks[0].state") == 'playing')
        se = await pg.evaluate("(()=>{const s=Looper.getSession(),t=s.tracks[0];const v=i=>{let q=t.dl[i*3]|(t.dl[i*3+1]<<8)|(t.dl[i*3+2]<<16);if(q&0x800000)q-=0x1000000;return q/8388607};return v(100)})()")
        check('Ideen speichern: nur hörbare Ebenen im Mix', abs(se - ref[0]) < 1e-4, se)
        await pg.click('#layers0 button[data-ly="1"]'); await pg.wait_for_timeout(200)
        check('wieder an → Summe', abs((await m())[0] - ref[0] - 0.1) < 1e-4)
        await pg.click('#layers0 button[data-ly="0"]'); await pg.wait_for_timeout(100)
        await pg.evaluate("window.confirm=()=>true;0")
        btn = pg.locator('#layers0 button[data-ly="1"]'); bb = await btn.bounding_box()
        await pg.mouse.move(bb['x'] + 5, bb['y'] + 5); await pg.mouse.down(); await pg.wait_for_timeout(900); await pg.mouse.up(); await pg.wait_for_timeout(200)
        check('Gedrückt halten = Ebene löschen (mit Rückfrage)', await pg.evaluate("Looper.layers(0)") == [False] and not await pg.is_visible('#layers0'), await pg.evaluate("Looper.layers(0)"))
        await pg.click('#undo0'); await pg.wait_for_timeout(200)
        check('Rückgängig: Ebene zurück, Stumm-Zustand mit', await pg.evaluate("Looper.layers(0)") == [False, True] and abs((await m())[0] - 0.1) < 1e-4, await pg.evaluate("Looper.layers(0)"))
        await pg.click('#layers0 button[data-ly="0"]'); await pg.wait_for_timeout(200)
        # ---------- 3. Übe-Tempo ----------
        L = await pg.evaluate("Looper.debug().tracks[0].L")
        await pg.select_option('#loopPractice', '50')
        await pg.wait_for_function("Looper._prac().rate === 0.5", timeout=20000); await pg.wait_for_timeout(300)
        pr = await pg.evaluate("Looper._prac()")
        check('50 %: Spur spielt gedehnten Puffer (doppelt so lang)', pr['tracks'][0]['src'] == 2 * L and not pr['tracks'][0]['orig'], (pr['tracks'][0], L))
        check('Drums/Drone/Takt: Tempo-Faktor 0,5', abs(pr['mul'] - 0.5) < 1e-6 and await pg.evaluate("Math.abs(Rhythm.nextBarTime() - audioCtx.currentTime) < 240/(parseFloat(bpm.value)*0.5) + 0.3"))
        a = await pg.evaluate("[Looper._prac().pos0, performance.now()]"); await pg.wait_for_timeout(1000); c = await pg.evaluate("[Looper._prac().pos0, performance.now()]")
        rate = ((c[0] - a[0]) % L) / ((c[1] - a[1]) / 1000) / sr
        check('Position läuft halb so schnell (Loop doppelt so lang abgespielt)', 0.42 < rate < 0.58, round(rate, 3))
        ana = await pg.evaluate("(async()=>{const s=Looper._prac();return s.tracks[0].src})()")
        await pg.click('#foot0'); await pg.wait_for_timeout(300)
        check('Aufnehmen gesperrt (Hinweis), Spur spielt weiter', 'gesperrt' in await pg.inner_text('#loopStatus') and await pg.evaluate("Looper.debug().tracks[0].state") == 'playing', await pg.inner_text('#loopStatus'))
        check('Anzeige „Übe-Tempo 50 %“', '50 %' in await pg.inner_text('#loopInfo'))
        await pg.click('#layers0 button[data-ly="1"]'); await pg.wait_for_timeout(1500)
        pr = await pg.evaluate("Looper._prac()")
        check('Ebene im Übe-Tempo umgeschaltet → neu gedehnt, läuft weiter', pr['tracks'][0]['src'] == 2 * L and await pg.evaluate("Looper.debug().tracks[0].state") == 'playing', pr['tracks'][0])
        await pg.click('#layers0 button[data-ly="1"]'); await pg.wait_for_timeout(1500)
        await pg.select_option('#loopPractice', '100'); await pg.wait_for_timeout(300)
        pr = await pg.evaluate("Looper._prac()")
        exact = await pg.evaluate("(()=>{const x=Looper._mixOf(0);return x.l.length})()")
        check('100 %: Original-Puffer, gedehnte Puffer freigegeben, Faktor 1', pr['rate'] == 1 and pr['tracks'][0]['orig'] and pr['tracks'][0]['src'] == L and pr['tracks'][0]['pb'] == 0 and pr['mul'] == 1, pr)
        a = await pg.evaluate("[Looper._prac().pos0, performance.now()]"); await pg.wait_for_timeout(1000); c = await pg.evaluate("[Looper._prac().pos0, performance.now()]")
        rate = ((c[0] - a[0]) % L) / ((c[1] - a[1]) / 1000) / sr
        check('100 %: Position läuft wieder in Echtzeit', 0.92 < rate < 1.08, round(rate, 3))
        same = await pg.evaluate("(()=>{const x=Looper._mixOf(0);let d=0;for(let i=0;i<x.l.length;i+=7)d=Math.max(d,Math.abs(x.l[i]-(Math.sin(i/20)*0.3+0.1)));return d})()")
        check('100 %: Audio exakt wie vorher', same < 1e-5, same)
        # ---------- 4. Fußpedal ----------
        await pg.evaluate("document.getElementById('pedalActsBox').open=true")
        check('Belegungstabelle: 4 Tasten × 3 Auswahlfelder', await pg.locator('#pedalActs select').count() == 12)
        st0 = await pg.evaluate("Looper.running()")
        await pg.keyboard.press('ArrowRight'); await pg.wait_for_timeout(300)
        check('Standard: Taste D (Pfeil →) = Alle starten/stoppen', await pg.evaluate("Looper.running()") != st0)
        await pg.select_option('select[data-slot="all"][data-w="tap"]', 'tuner'); await pg.wait_for_timeout(100)
        check('Belegung gespeichert', '"tuner"' in await pg.evaluate("localStorage.getItem('3nps-pedal-acts')"))
        await pg.focus('#pedalSink'); await pg.keyboard.press('ArrowRight'); await pg.wait_for_timeout(1200)
        check('Taste D neu belegt: Stimmgerät an', await pg.evaluate("Looper.tunerOn()") and await pg.is_visible('#tunerDlg'))
        await pg.keyboard.press('ArrowRight'); await pg.wait_for_timeout(300)
        check('… und wieder aus', not await pg.evaluate("Looper.tunerOn()"))
        await pg.select_option('select[data-slot="foot1"][data-w="tap"]', 'none'); await pg.select_option('select[data-slot="foot1"][data-w="hold"]', 'pracNext'); await pg.focus('#pedalSink')
        await pg.keyboard.down('ArrowDown'); await pg.wait_for_timeout(950); await pg.keyboard.up('ArrowDown')
        await pg.wait_for_function("Looper._prac().rate !== 1 || !Looper._prac().busy", timeout=20000); await pg.wait_for_timeout(1500)
        check('Taste B gedrückt halten = Übe-Tempo nächste Stufe (90 %), Tippen „nichts“', await pg.evaluate("Looper._prac().rate") == 0.9 and await pg.evaluate("Looper.debug().tracks[1].state") == 'empty', await pg.evaluate("Looper._prac().rate"))
        await pg.select_option('select[data-slot="foot2"][data-w="dbl"]', 'prac'); await pg.focus('#pedalSink')
        await pg.keyboard.press('ArrowLeft'); await pg.wait_for_timeout(80); await pg.keyboard.press('ArrowLeft'); await pg.wait_for_timeout(700)
        check('Taste C doppelt tippen = Übe-Tempo aus (100 %), kein einfacher Tipp', await pg.evaluate("Looper._prac().rate") == 1 and await pg.evaluate("Looper.debug().tracks[2].state") == 'empty', await pg.evaluate("Looper._prac().rate"))
        await pg.click('#pedalActsReset')
        check('Standard wiederherstellen', await pg.evaluate("localStorage.getItem('3nps-pedal-acts')") is None and await pg.input_value('select[data-slot="all"][data-w="tap"]') == 'all')
        check('keine Skriptfehler', not errs, errs[:3])
        await b.close()
    print('\n%d/%d' % (ok, tot)); sys.exit(0 if ok == tot else 1)
asyncio.run(main())
